import hashlib,json
from datetime import datetime,timezone
from pathlib import Path
c=Path(__file__).resolve().parent;page=c/'party-api-pages/page-25.json';posts={p['id']:p for p in json.loads(page.read_text())}
notes={3382:'Şükran Doğan 2020 bütçesi ve vergi paketi hakkında asgari ücretin vergi dışı bırakılması, dolaylı vergi yükünün kaldırılması ve eğitim/sağlığa kaynak talep eder. Vergi dilimi, araç sayıları ve Cumhurbaşkanlığı ödeneklerine ilişkin sayılar tasarı, kanun ve bütçe gerçekleşmeleriyle ayrı doğrulanmalı.',3379:'EMEP Genel Merkezi 8 Ekim 2019 yayımlı açıklamasında Fırat’ın doğusunda operasyonu eleştirir ve TBMM milletvekillerine tezkereye hayır oyu çağrısı yapar. API yayım saati 13.18.39; metin teklif numarası vermez. Aynı günkü 3/878 Irak-Suriye tezkere görüşmesi ile ilişki ve önce-sonra bağı özgün Meclis kaydıyla ayrıca sınanmalı; 3/879 Mali/Orta Afrika ayrı.',3377:'Selma Gürkan 7 Ekim 2019’da Suriye’ye yönelik askerî operasyona karşı çıkıp hükümeti bu yoldan dönmeye çağırır. Güvenlik ve diğer devletlerin amaçları hakkındaki değerlendirmeler partinin görüşüdür; tezkere veya operasyonun sonucu değildir.',3374:'Gürkan yüzde 40 artı 1 ve yüzde 50 artı 1 tartışması bağlamında seçim barajından ziyade demokratikleşmeyi savunur, atanmışlar yönetimi yerine yöneticilerin seçim ve halkça denetlenmesini ister. Metin bir anayasa değişikliği veya gerçekleşmiş yeni eşik göstermez.'}
parts=[]
for pid,note in notes.items():
 p=posts[pid];body=p['content']['rendered'];digest=hashlib.sha256(body.encode()).hexdigest();parts.append(dict(post_id=pid,url=p['link'],page=str(page),api_date=p['date'],body_sha256=digest,start_char=0,end_char=len(body),slice_sha256=digest,body_temporal_status='last_modified_at_or_before_cutoff',reading_note=note))
out=dict(tranche_id='0410-emep-api-277',read_at=datetime.now(timezone.utc).isoformat(),method='Özgün API HTML gövdeleri doğrudan okundu; tam gövdeler ve aralıklar UTF-8 SHA-256 ile bağlandı.',research_leads=[{'post_id':3379,'lead':'8 Ekim 2019 tezkereye hayır çağrısı; TBMM 27/3/3 ilk oturum 15.00, Irak-Suriye 3/878 ve kabul tutanakta görünüyor. Aynı gün kabul edilen Mali/Orta Afrika 3/879 değildir.','preliminary_primary':'https://www5.tbmm.gov.tr/tutanaklar/TUTANAK/TBMM/d27/c018/tbmm27018003.pdf','open':'Özgün TBMM baytlarını arşivleyip 3/878 kimliğini, kabulü, gün içi sıralamayı ve mevcut paketlerle eş olay bulunup bulunmadığını bağımsız sınamadan aday sayılmadı.'}],limitations=['Belirtilen vergi, askerî ve seçim iddiaları bağımsız doğrulanmadı.','Gün içi karşılaştırmada API zaman dilimi ve resmî tutanak olayı ayrı doğrulanmalıdır.','Kapsam kapanışı yapılmadı.'],parts=parts,closure_refs=[])
assert sum(p['end_char'] for p in parts)<48000
with (c/'party-api-277-source-reading.json').open('x') as f:json.dump(out,f,ensure_ascii=False,indent=2);f.write('\n')
print('API277_READING_OK',sum(p['end_char'] for p in parts))
